ALTER TABLE parties ADD COLUMN entity_type TEXT NOT NULL DEFAULT 'individual' CHECK(entity_type IN ('individual','business'));
ALTER TABLE parties ADD COLUMN street TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN building_number TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN district TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN city TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN postal_code TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN country_code TEXT NOT NULL DEFAULT 'SA';
ALTER TABLE parties ADD COLUMN id_scheme TEXT NOT NULL DEFAULT '';
ALTER TABLE parties ADD COLUMN id_number TEXT NOT NULL DEFAULT '';
ALTER TABLE invoices ADD COLUMN invoice_kind TEXT NOT NULL DEFAULT 'simplified' CHECK(invoice_kind IN ('standard','simplified'));
ALTER TABLE invoices ADD COLUMN document_code TEXT NOT NULL DEFAULT '388' CHECK(document_code IN ('388','381','383'));
ALTER TABLE invoices ADD COLUMN supply_date TEXT;
ALTER TABLE invoices ADD COLUMN environment TEXT NOT NULL DEFAULT 'legacy' CHECK(environment IN ('legacy','development','simulation','production'));
ALTER TABLE invoice_lines ADD COLUMN tax_category TEXT NOT NULL DEFAULT 'S' CHECK(tax_category IN ('S','Z','E','O'));
ALTER TABLE invoice_lines ADD COLUMN exemption_code TEXT NOT NULL DEFAULT '';
ALTER TABLE invoice_lines ADD COLUMN exemption_reason TEXT NOT NULL DEFAULT '';
ALTER TABLE invoice_lines ADD COLUMN unit_code TEXT NOT NULL DEFAULT 'PCE';
ALTER TABLE items ADD COLUMN tax_category TEXT NOT NULL DEFAULT 'S' CHECK(tax_category IN ('S','Z','E','O'));
ALTER TABLE items ADD COLUMN exemption_code TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN exemption_reason TEXT NOT NULL DEFAULT '';
DROP TRIGGER inv_nu;
UPDATE invoices SET document_code=type;
CREATE TRIGGER inv_nu BEFORE UPDATE ON invoices WHEN OLD.status='issued' BEGIN SELECT RAISE(ABORT,'الفاتورة الصادرة غير قابلة للتعديل: أصدر إشعارًا دائنًا');END;
CREATE TABLE invoice_tax_totals(invoice_id INTEGER NOT NULL REFERENCES invoices(id),tax_category TEXT NOT NULL,vat_rate REAL NOT NULL,exemption_code TEXT NOT NULL DEFAULT '',exemption_reason TEXT NOT NULL DEFAULT '',taxable INTEGER NOT NULL,vat INTEGER NOT NULL,PRIMARY KEY(invoice_id,tax_category,vat_rate,exemption_code));
INSERT INTO invoice_tax_totals(invoice_id,tax_category,vat_rate,taxable,vat) SELECT invoice_id,'S',vat_rate,SUM(net),SUM(vat) FROM invoice_lines GROUP BY invoice_id,vat_rate;
CREATE TABLE invoice_documents(invoice_id INTEGER NOT NULL REFERENCES invoices(id),kind TEXT NOT NULL CHECK(kind IN ('xml_candidate','signed_xml','cleared_xml')),content TEXT NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(invoice_id,kind));
CREATE TABLE regulatory_queue(invoice_id INTEGER PRIMARY KEY REFERENCES invoices(id),operation TEXT NOT NULL CHECK(operation IN ('reporting','clearance')),state TEXT NOT NULL DEFAULT 'blocked' CHECK(state IN ('blocked','ready','sending','accepted','rejected','retry')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,last_error TEXT NOT NULL DEFAULT '',last_response TEXT,updated_at TEXT NOT NULL);
CREATE TABLE regulatory_attempts(id INTEGER PRIMARY KEY,invoice_id INTEGER NOT NULL REFERENCES invoices(id),started_at TEXT NOT NULL,finished_at TEXT NOT NULL,outcome TEXT NOT NULL,response_code INTEGER,response_summary TEXT NOT NULL);
CREATE TABLE compliance_state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER,event TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'سجل التدقيق غير قابل للتعديل');END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'سجل التدقيق غير قابل للحذف');END;
CREATE TRIGGER documents_no_update BEFORE UPDATE ON invoice_documents BEGIN SELECT RAISE(ABORT,'المستند المؤرشف ثابت');END;
CREATE TRIGGER documents_no_delete BEFORE DELETE ON invoice_documents BEGIN SELECT RAISE(ABORT,'المستند المؤرشف ثابت');END;
CREATE TRIGGER attempts_no_update BEFORE UPDATE ON regulatory_attempts BEGIN SELECT RAISE(ABORT,'سجل الإرسال ثابت');END;
CREATE TRIGGER attempts_no_delete BEFORE DELETE ON regulatory_attempts BEGIN SELECT RAISE(ABORT,'سجل الإرسال ثابت');END;
CREATE TRIGGER tax_totals_no_update BEFORE UPDATE ON invoice_tax_totals BEGIN SELECT RAISE(ABORT,'تفصيل الضريبة ثابت');END;
CREATE TRIGGER tax_totals_no_delete BEFORE DELETE ON invoice_tax_totals BEGIN SELECT RAISE(ABORT,'تفصيل الضريبة ثابت');END;
DROP TRIGGER il_nu;
CREATE TRIGGER il_nu BEFORE UPDATE ON invoice_lines WHEN (SELECT status FROM invoices WHERE id=OLD.invoice_id)='issued' OR (SELECT status FROM invoices WHERE id=NEW.invoice_id)='issued' BEGIN SELECT RAISE(ABORT,'بنود الفاتورة الصادرة مقفلة');END;
UPDATE local_meta SET value='4' WHERE key='schema_version';
CREATE TABLE journal_seals(entry_id INTEGER PRIMARY KEY REFERENCES journal_entries(id));
INSERT INTO journal_seals(entry_id) SELECT id FROM journal_entries;
CREATE TRIGGER journal_no_late_insert BEFORE INSERT ON journal_lines WHEN EXISTS(SELECT 1 FROM journal_seals WHERE entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'القيد المحاسبي مقفل');END;
CREATE TRIGGER journal_seals_no_update BEFORE UPDATE ON journal_seals BEGIN SELECT RAISE(ABORT,'قفل القيد ثابت');END;
CREATE TRIGGER journal_seals_no_delete BEFORE DELETE ON journal_seals BEGIN SELECT RAISE(ABORT,'قفل القيد ثابت');END;
